/**
 * Differential parity harness for the interpreted IR ROW kernel (M4 of {@code .agent/lmdb-kernel-interpreter-execplan}
 * ): every row query runs once through the compiled tier (janino on, synchronous) and once through
 * {@link LmdbNativeKernelInterpreter#forRows} (janino off), asserting identical result multisets — plus, per query, an
 * {@code OPENED}-delta proof that the interpreted arm actually served through the row kernel rung. The fixture mirrors
 * the aggregate parity test's MEDICAL shapes, loaded in one transaction with the direct-adjacency readiness gate.
 */
class LmdbNativeKernelInterpreterRowParityTest {

	private static final String EX = "http://example.com/med/";

	private static final String[] PROPERTIES = {
			"rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.thresholdRows",
			"rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.factorizedRows.enabled",
			"rdf4j.lmdb.factorizedTail.enabled",
			"rdf4j.lmdb.nativeBatch.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.irAggregateParallel.enabled",
			"rdf4j.lmdb.nativeHashJoin.minRows" };

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new HashMap<>();
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
		// Remove competing strategy proposals so the irKernel route (compiled or interpreted) actually serves.
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.threads", "1");
		System.setProperty("rdf4j.lmdb.irAggregateParallel.enabled", "false");

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore store = new LmdbStore(dataDir, config);
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI name = vf.createIRI(EX, "name");
			IRI age = vf.createIRI(EX, "age");
			IRI hasEncounter = vf.createIRI(EX, "hasEncounter");
			IRI date = vf.createIRI(EX, "date");
			IRI diagnosis = vf.createIRI(EX, "diagnosis");
			IRI medication = vf.createIRI(EX, "medication");
			IRI drugA = vf.createIRI(EX, "drugA");
			IRI drugB = vf.createIRI(EX, "drugB");
			// Single transaction, deliberately (per-add autocommit wedges direct adjacency into a revision gap).
			conn.begin();
			for (int i = 0; i < 30; i++) {
				IRI patient = vf.createIRI(EX, "patient" + i);
				conn.add(patient, name, vf.createLiteral("Patient " + i));
				conn.add(patient, age, vf.createLiteral(20 + (i % 7) * 9));
				int encounters = 1 + i % 3;
				for (int j = 0; j < encounters; j++) {
					IRI encounter = vf.createIRI(EX, "enc" + i + "_" + j);
					conn.add(patient, hasEncounter, encounter);
					int month = 1 + (i + j) % 4;
					conn.add(encounter, date,
							vf.createLiteral("2026-0" + month + "-1" + j, org.eclipse.rdf4j.model.vocabulary.XSD.DATE));
					if ((i + j) % 2 == 0) {
						conn.add(encounter, diagnosis, vf.createIRI(EX, "diag" + (i + j) % 4));
					}
				}
				if (i % 3 == 0) {
					conn.add(patient, medication, drugA);
				}
				if (i % 5 == 0) {
					conn.add(patient, medication, drugB);
				}
			}
			conn.commit();
		}
		try {
			assertThat(store.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		for (Map.Entry<String, String> property : previousProperties.entrySet()) {
			if (property.getValue() == null) {
				System.clearProperty(property.getKey());
			} else {
				System.setProperty(property.getKey(), property.getValue());
			}
		}
	}

	@Test
	void plainJoinProjection() {
		// Baseline row shape: two-pattern join, plain Emit terminal.
		assertParityInterpreterServed(prefixes()
				+ "SELECT ?p ?d WHERE { ?p ex:hasEncounter ?e . ?e ex:date ?d }");
	}

	@Test
	void distinctProjection() {
		// Pins the DISTINCT Emit guard (hash or aligned-prefix dedup per the distinct-sinking lowering).
		assertParityInterpreterServed(prefixes()
				+ "SELECT DISTINCT ?p WHERE { ?p ex:hasEncounter ?e . ?e ex:diagnosis ?dg }");
	}

	@Test
	void orderByValueWithLimitOffset() {
		// Pins OutputMods on the Emit terminal (ORDER BY comparator + OFFSET/LIMIT window; topKRows path). Ordered
		// results compare as lists, not multisets: the window itself must match.
		assertOrderedParity(prefixes()
				+ "SELECT ?p ?d WHERE { ?p ex:hasEncounter ?e . ?e ex:date ?d } ORDER BY ?d ?p LIMIT 5 OFFSET 2");
	}

	@Test
	void optionalNullArmsBindUnboundSlots() {
		// OPTIONAL null arms: -1 columns must leave the RowState slot unbound through KernelRowCursor.
		assertParityInterpreterServed(prefixes()
				+ "SELECT ?p ?m WHERE { ?p ex:hasEncounter ?e . OPTIONAL { ?p ex:medication ?m } }");
	}

	@Test
	void unorderedLimitCutoff() {
		// The unordered-limit early cutoff (D15): both arms run the same lowered pipeline in the same deterministic
		// order, so the first rows agree even though LIMIT-without-ORDER is nondeterministic in general.
		assertParityInterpreterServed(prefixes()
				+ "SELECT ?p ?e WHERE { ?p ex:hasEncounter ?e . ?e ex:date ?d } LIMIT 7");
	}

	@Test
	void valueFilterOnJoin() {
		// A value-tier FILTER riding the row pipeline (hooks.testFilter or residual filters on the wrapper cursor).
		assertParityInterpreterServed(prefixes()
				+ "SELECT ?p ?age WHERE { ?p ex:age ?age . ?p ex:hasEncounter ?e . FILTER(?age > 40) }");
	}

	@Test
	void hashJoinBuildProbe() {
		// Pins HashBuild/HashProbe ("hb0(...){...};"/"hp0("): the in-kernel hash join is row-rung v1 (ExecPlan D12)
		// and engages when LmdbNativeHashJoin's cost gate prefers building one side; the gate's 4096-row floor is
		// lowered so the small fixture can reach it. Census-confirmed; parity plus engagement proves the
		// interpreted LongRowMap build/probe produces identical chains.
		System.setProperty("rdf4j.lmdb.nativeHashJoin.minRows", "1");
		assertParityInterpreterServed(prefixes()
				+ "SELECT ?e ?d ?p WHERE { ?e ex:date ?d . ?p ex:hasEncounter ?e }");
	}

	@Test
	void distinctDeadObjectPruning() {
		// Census shows this lowers to "EA(a0,k0,x1,sip);P(a1,v0->2);emit(2,distinct)" — the sip-driven root keeps
		// its value column, so the SipKeyProbe fusion does NOT fire: no current lowering (row or aggregate) emits a
		// keys-only EnumerateAdjKeys adjacent to a Probe (ExecPlan D12 addendum). SKP execution parity is pinned by
		// the direct-IR differential in LmdbNativeKernelIrEmitterTest instead.
		assertParityInterpreterServed(prefixes()
				+ "SELECT DISTINCT ?m WHERE { ?p ex:name ?n . ?p ex:medication ?m }");
	}

	// ------------------------------------------------------------------

	private void assertParityInterpreterServed(String query) {
		List<String> compiled = canonical(rows(query, true));
		LmdbNativeKernelExecution.resetMetrics();
		List<String> interpreted = canonical(rows(query, false));
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("the interpreted arm must serve this query through the row kernel interpreter")
				.isPositive();
	}

	/** Ordered queries compare row lists positionally (the ORDER BY window must be identical, not just the bag). */
	private void assertOrderedParity(String query) {
		List<String> compiled = ordered(rows(query, true));
		LmdbNativeKernelExecution.resetMetrics();
		List<String> interpreted = ordered(rows(query, false));
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("the interpreted arm must serve this query through the row kernel interpreter")
				.isPositive();
	}

	private List<BindingSet> rows(String query, boolean janino) {
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", Boolean.toString(janino));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = ordered(rows);
		result.sort(String::compareTo);
		return result;
	}

	private static List<String> ordered(List<BindingSet> rows) {
		List<String> result = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>(row.size());
			for (Binding binding : row) {
				bindings.add(binding.getName() + "=" + binding.getValue());
			}
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		return result;
	}

	private static String prefixes() {
		return "PREFIX ex: <" + EX + ">\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";
	}
}
